import re

_UNIT_SECONDS = {"d": 86400, "h": 3600, "m": 60, "s": 1}
_PATTERN = re.compile(r"(?:(\d+)d)?(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?")


def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("empty duration string")
    match = _PATTERN.fullmatch(s)
    if not match or all(g is None for g in match.groups()):
        raise ValueError(f"invalid duration string: {s!r}")
    d, h, m, sec = match.groups()
    return (
        (int(d) if d else 0) * 86400
        + (int(h) if h else 0) * 3600
        + (int(m) if m else 0) * 60
        + (int(sec) if sec else 0)
    )
