function compareSemver(a, b) {
  const parse = (v) => {
    const [core, prerelease] = v.split('-');
    const [major, minor, patch] = core.split('.').map(Number);
    const pre = prerelease === undefined ? [] : prerelease.split('.');
    return { major, minor, patch, pre };
  };
  const A = parse(a);
  const B = parse(b);

  const cmp = (x, y) => (x < y ? -1 : x > y ? 1 : 0);

  for (const key of ['major', 'minor', 'patch']) {
    const c = cmp(A[key], B[key]);
    if (c !== 0) return c;
  }

  const hasPre = A.pre.length || B.pre.length;
  if (!hasPre) return 0;

  // A version with a pre-release is lower than the same version without one.
  if (A.pre.length === 0) return 1;
  if (B.pre.length === 0) return -1;

  const len = Math.max(A.pre.length, B.pre.length);
  for (let i = 0; i < len; i++) {
    const pa = A.pre[i];
    const pb = B.pre[i];
    if (pa === undefined) return -1; // A has fewer fields -> A lower
    if (pb === undefined) return 1;  // B has fewer fields -> B lower
    const paNum = /^\d+$/.test(pa);
    const pbNum = /^\d+$/.test(pb);
    if (paNum && pbNum) {
      const c = cmp(Number(pa), Number(pb));
      if (c !== 0) return c;
    } else {
      const c = cmp(pa, pb);
      if (c !== 0) return c;
    }
  }
  return 0;
}
